33	// One blocking TLM access against `mem`, asserting an OK response. `data` is
34	// the write source for TLM_WRITE / the read destination for TLM_READ.
35	template<typename Mem>
36	inline void tlm_access(Mem& mem, tlm::tlm_command cmd, uint64_t addr,
37	                       std::span<uint8_t> data)
38	{
39	  tlm::tlm_generic_payload gp;
40	  gp.set_command(cmd);
41	  gp.set_address(addr);
42	  gp.set_data_ptr(data.data());
43	  gp.set_data_length(data.size());
44	  gp.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
45	  sc_core::sc_time delay = sc_core::SC_ZERO_TIME;
46	  mem.b_transport(gp, delay);
47	  REQUIRE(gp.get_response_status() == tlm::TLM_OK_RESPONSE);
48	}
49	
50	template<typename Mem>
51	inline void tlm_write(Mem& mem, uint64_t addr, std::span<uint8_t> data)
52	{
53	  tlm_access(mem, tlm::TLM_WRITE_COMMAND, addr, data);
54	}
55	
56	template<typename Mem>
57	inline void tlm_read(Mem& mem, uint64_t addr, std::span<uint8_t> out)
58	{
59	  tlm_access(mem, tlm::TLM_READ_COMMAND, addr, out);
60	}
